package com.auditlog.application.service;
import com.auditlog.application.command.AppendAuditEventCommand; import com.auditlog.infrastructure.persistence.entity.*; import com.auditlog.infrastructure.persistence.repository.*; import com.auditlog.support.exception.*; import com.fasterxml.jackson.databind.ObjectMapper; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.time.*; import java.util.UUID;
@Service public class PayloadRedactionService { private final AuditEventRepository events; private final PayloadRedactionRepository redactions; private final AuditEventAppendService append; private final ObjectMapper json; private final Clock clock;
 public PayloadRedactionService(AuditEventRepository e,PayloadRedactionRepository r,AuditEventAppendService a,ObjectMapper j,Clock c){events=e;redactions=r;append=a;json=j;clock=c;}
 @Transactional public UUID redact(UUID targetId,String pointer,String reason,String policy,String actor){ AuditEventEntity target=events.findById(targetId).orElseThrow(()->new AuditLogException(ErrorCode.AUDIT_EVENT_NOT_FOUND,"Audit event not found")); if(redactions.existsByTargetEventIdAndJsonPointer(targetId,pointer)) throw new AuditLogException(ErrorCode.PERSISTENCE_CONFLICT,"Payload path is already redacted"); var details=json.createObjectNode().put("targetEventId",targetId.toString()).put("jsonPointer",pointer).put("reason",reason).put("policyVersion",policy); var action=append.append(new AppendAuditEventCommand("PAYLOAD_REDACTED",actor,target.getResourceType(),target.getResourceId(),details)); redactions.save(new PayloadRedactionEntity(UUID.randomUUID(),targetId,action.eventId(),pointer,reason,policy,actor,Instant.now(clock),"projection-only")); return action.eventId(); }
}
